sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float amount;
uniform float scale;
uniform float complexity;
uniform float speed;
uniform float seed;
uniform float kind;
uniform float pin;
uniform float opacity;
float4 tex(float2 p) {
    return float4(image.eval(clamp(p, float2(0.0), size)));
}
half4 fin(float4 o, float4 r, float op) {
    return half4(mix(o, r, saturate(op)));
}
float hash21(float2 p) {
    return fract(sin(dot(p, float2(127.1, 311.7))) * 43758.5453);
}
float vnoise(float2 p) {
    float2 i = floor(p);
    float2 f = fract(p);
    f = f * f * (3.0 - 2.0 * f);
    float a = hash21(i);
    float b = hash21(i + float2(1.0, 0.0));
    float c = hash21(i + float2(0.0, 1.0));
    float d = hash21(i + float2(1.0, 1.0));
    return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}
float fbm(float2 p, float oct, float rough) {
    float v = 0.0;
    float a = 0.5;
    float norm = 0.0;
    for (int i = 0; i < 6; i++) {
        if (float(i) >= oct) break;
        v += a * vnoise(p);
        norm += a;
        p = p * 2.03 + float2(11.7, 5.3);
        a *= rough;
    }
    return v / max(norm, 0.0001);
}
half4 main(float2 coord) {
    float4 c = tex(coord);
    float2 p = coord / max(scale, 1.0) + seed * 7.3;
    float t = time * speed;
    float nx = fbm(p + float2(t, 0.0), complexity, 0.5);
    float ny = fbm(p + float2(5.2, 1.3 - t), complexity, 0.5);
    float2 n = float2(nx, ny) * 2.0 - 1.0;
    if (kind > 0.5) n = float2(abs(n.x), abs(n.y)) * 2.0 - 1.0;
    float2 uv = coord / size;
    float edge = smoothstep(0.0, 0.15, uv.x) * (1.0 - smoothstep(0.85, 1.0, uv.x)) * smoothstep(0.0, 0.15, uv.y) * (1.0 - smoothstep(0.85, 1.0, uv.y));
    return fin(c, tex(coord + n * amount * mix(1.0, edge, pin)), opacity);
}
